<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfile;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserProfileCreateEvent extends UserProfileEvent implements PublicEvent
{
    public function __construct(
        UserProfile $payload
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-profile.create';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return [];
    }
}
